    public static class CyprianKamilNorwid
    {
        public static readonly Quote[] Quotes = new Quote[]
        {
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Apostołstwo nie jest dyplomacją i kuglarstwem, i kabalistyką, ale proroctwem szczerym.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Autorów sądzą ich dzieła.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "cisza jest głosów – zbieraniem (…).", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Cisza – niekiedy tylko pająk siatką wzruszy, Lub przed oknem topolę wietrzyk pomuskuje; Och! jak lekko oddychać, słodko marzyć duszy – Tu mi gwar, tu mi uśmiech myśli nie krępuje.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Coś ty Atenom zrobił, Sokratesie?", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Coś ty ludziom uczynił, Mickiewiczu?", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Czarnoleskiej ja rzeczy chcę!", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Czemu, Cieniu, odjeżdżasz, ręce złamawszy na pancerz (…).", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Czemu mi smutno i czemu najsmutniej, Mamże ci śpiewać ja — czy świat i czas?…", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Czułość – bywa jak pełny wojen krzyk, I jak szemrzących źródeł prąd, I jako wtór pogrzebny…", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Czy ten ptak kala gniazdo, co je kala, Czy ten, co mówić o tym nie pozwala?", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Do kraju tego, gdzie kruszynę chleba Podnoszą z ziemi przez uszanowanie Dla darów Nieba… Tęskno mi, Panie… Do kraju tego, gdzie winą jest dużą Popsować gniazdo na gruszy bocianie, Bo wszystkim służą… Tęskno mi, Panie…", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Dobrym u mnie historykiem Jest mąż, co przyszedł pod koniec epoki, I widzi rozkład z głuchym serca ściskiem, I proste fakta pisząc, jest głęboki – I żadną partią, ani się nazwiskiem Promiennym uwieść nie dał jednostronnie…", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Głosem narodu jest harmonia ojczysta, mieczem – jedność i zgoda, celem – prawda.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Gorzki to chleb jest polskość…", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Heroizm nie jest w samych bitwach, ale na wszystkich polach życia i nieustannie. Owszem bitwy dlatego tylko bywają, iż heroizm nie bywa pierwej na polach życia praktykowany.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "I stąd największym prosty lud poetą, Co nuci z dłońmi ziemią brązowemi.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "I zagrałem... I jeszcze mi smutniej.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Jeśli mi Polska ma być anarchiczną, Lub socjalizmu rozwinąć pytanie, To już ja wolę tę panslawistyczną, Która pod Carem na wieki zostanie!", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Jedyna miłość, która nas nigdy nie zdradzi, to miłość własna.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Jestem z narodu, w którym od lat blisko stu każda książka wychodzi za późno, a każdy czyn za wcześnie.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Jestże się poetą, czyli raczej tylko bywa się?", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Jękły głuche kamienie. Ideał sięgnął bruku.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "kto inny ma laur i nadzieję, Ja – jeden zaszczyt: być człekiem.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Kto kocha – małe mu ogromnieje i lada promyk zolbrzymia nadzieję.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "kto prawdę mówi, ten niepokój wszczyna.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Kto ukochał ogół, a nie ukochał pojedynczo – to Robespierre. Kto ukochał tylko pojedynczych, a ogół zdeptał, to Neron.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Któż nie chciałby stać się przez szczęście głupszy, zamiast być mądrzejszym przez szkodę?", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Miejcie trochę pokory i wyznajcie, żem nie wariat – że nie ciemno piszę, ale Wy ciemno czytacie.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Miłości! w tobie jednej odpocznienie I moc, i bytu oś; w tobie sumienie.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Narodowy artysta organizuje wyobraźnię, jak na przykład polityk narodowy organizuje siły stanu.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Nie lubię miasta, nie lubię wrzasków, I hucznych zabaw, i świetnych blasków, Bo ja chłop jestem – bo moje oczy Wielmożna świetność kole i mroczy. Miasto – złocony kraniec przepaści!", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Nie miecz, nie tarcz – bronią Języka, lecz – arcydzieła!", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Nie szukaj świata, kochaj i… bądź zdrowa… A za umarłych módl się – po weselu.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Nie trzeba kłaniać się Okolicznościom, a Prawdom kazać, by stały za drzwiami.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Nie za sobą z krzyżem Zbawiciela, ale za Zbawicielem z 'krzyżem swoim', ta jest zasada wszechharmonji społecznej w chrześcijaństwie – ten jest tego, co zowią materjalnie 'specjalnościami', rytm i akord. Ta to jest nareszcie tajemnica ruchu sprawiedliwego.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Nowa epoka nie chce zeszłego natchnienia.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "O! ty ukochana Ludzkości Chrześciańska – czy taić ci o tem Że jesteś nieskończenie szanowne nic-potem? — Osiemnaście więc wieków trwasz? a taka próżnia We wszystkiem – mało gdzie cię myśl wyższa odróżnia Od pogan, z których żyjesz.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Oczy spokojne i głębokie, do zaczarowanych jezior podobne – gest arcyszlachetny – i coś z zamyślonego łabędzia we wszystkości poruszeń.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Ojczyzna – to wielki zbiorowy obowiązek.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Oryginalność jest to sumienność w obliczu źródeł.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Piekło to ledwie niemożność miłości (…)", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "piękno na to jest, by zachwycało – do pracy Praca, by się zmartwychwstało.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Polacy są wspaniałym narodem i bezwartościowym społeczeństwem.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Ponad wszystkie wasze uroki, Ty! Poezjo, i ty Wymowo, Jeden – wiecznie będzie wysoki: Odpowiednie dać rzeczy – słowo!", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Przeszłość – to jest dziś, tylko cokolwiek dalej. Nie jakieś tam coś, gdzieś, gdzie nigdy ludzie nie bywali.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Przyszłość albowiem zdobywają te trzy rzeczy: duch, cierpliwość i dopełnienie – ale wcale nie krew: to bajka.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Rubaszność – zatrzymany w postępie heroizm.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Słowo – jest czynu testamentem (…)", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Słowo jest ogień – milczenie jest lawa.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Smutno życie porzucić i zamknąć się w sobie. Żyć czuciem własnym, własnych marzeń przędzą", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Szczęśliwi, którzy teraz płaczecie, bowiem śmiać się będziecie.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Tak to więc wszystko, na tym słusznie przeklętym świecie, wszystko, co się poczyna z dziewiczego natchnienia myśli, musi być sprzedanym za 30 srebrników.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Teraz więc, póki jeszcze Niebo jest łaskawsze, Póki jasność Twych spojrzeń jeszcze dla mnie świeci, A zasłona przyszłości czarnych chmur nie wznieci, Żegnam Ciebie, o luba, żegnam Cię na zawsze.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "U nas (…) energia wyprzedza zawsze inteligencję – i co pokolenie jest rzeź.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Walka jest normalnym zadaniem Ludzkości – bitwa nie.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Wolność nie jest to dziewica.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Wszystko bierze swą moc z ideałów.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Z rzeczy świata tego zostaną tylko dwie, Dwie tylko: poezja i dobroć… i nic więcej.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Zamiast uważać na czytelników i radzić tę kokieterię pisarską drugim – lepiej jest czytać uważnie to, co nie uważając na czytelników napisane.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Źle, źle zawsze i wszędzie. Ta nić czarna się przędzie: Ona za mną, przede mną i przy mnie, Ona w każdym oddechu, Ona w każdym uśmiechu, Ona we łzie, w modlitwie i w hymnie…", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Żaden król polski nie stał na szafocie, A więc nam Francuz powie – 'buntowniki'! Żaden mnich polski nie bluźnił wszech-cnocie, Więc nam heretyk powie – 'heretyki'! Żaden pług polski cudzej nie pruł ziemi, Więc poczytani będziem jak 'złodzieje'.", Author = "Cyprian Kamil Norwid" },
            new Quote { Id = "https://pl.wikiquote.org/wiki/Cyprian_Kamil_Norwid", Text = "Że coraz łatwiej przychodzi powiedzieć, Ze snu się budząc: „Wróćmyż znów do snu.”", Author = "Cyprian Kamil Norwid" },
        };
    }
